ruleContent.nextContentUrl:
@js:
if(!baseUrl.match(/_2/)){
page="{{@@class.chapterPages@tag.a.-1@text}}"
if(page!=""){
page=String(page).match(/(\d+)/)[1];
list=[];
for(i=2;i<=page;i++){
	if(i==2 || i==5){
	url=baseUrl.replace(/(_\d+)*\.html$/,'_'+i+'.html,{"webView": true}')
	}else if(i==3){
		url=baseUrl.replace(/(_\d+)*\.html$/,'_'+i+'.html,{"method":"POST","body":"err=1"}')
		}else{
		url=baseUrl.replace(/(_\d+)*\.html$/,'_'+i+'.html')
	}
	list.push(url)
	}
list
}
}

ruleToc.nextTocUrl:
@js:
page=result.match(/第1\/(\d+)页/)[1];
if(!baseUrl.match(/_2/)){
list=[];
for(i=2;i<=page;i++){
	list.push(baseUrl.replace(/\/$/,'_'+i+'/'))
	}
list
}

source.exploreUrl:
@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://m.yeshuku.com/modules/article/articlefilter.php";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".sch-sel a");
    push("🔥分类小说🔥", null, 1);
    for (var i in a) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.33;
        title = String(title).replace(/\s/g, "");
        url = String(url)+ "?page={{page}}";      
        push(title, url, size);
  }

} else {
  java.toast("🤔列表刷新失败！！！");     
} 
JSON.stringify(result);

